"""Original Biology authoring, group 3D. No examination wording is used."""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from authoring_support import Author
A=Author(3,group='3D')

def E(o,h,c,p='',src=None):
    ids=A.entry(o,h,c,p,source=src)
    if src and src[0]=='SRC-SYL-6116':
        for claim in A.claims[-len(c)+1:]:
            claim['evidence']=[]
            claim['notes']=['The cited syllabus defines the preceding term but is not an adequate scientific reference for this additional explanatory claim; source or teacher-knowledge verification required.']
    return ids
def C(o,t,p,a,g,pending=False):
    s=next(s for s in A.wo['item_slots'] if s['objective_id']=='OBJ-6116-'+o and s['subtype']==t)
    demand=None
    if s['assessment_objectives']==['AO2']:
        demand={'new_input':p,'inference':a,'classification':'reasoning from the supplied case, rather than a renamed recall prompt.'}
    A.card(o,t,p,a,g,pending=pending,demand=demand)
S=lambda sec:('SRC-OSB2E',sec,'paraphrase')
SY=lambda p,sec:('SRC-SYL-6116',f'printed p.{p}, {sec}','direct')

E('3.10.1-01','Aerobic respiration',['Aerobic respiration is the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy.','Respiration transfers energy from nutrients for cell activities; breathing moves air into and out of lungs.'], 'A seed, a leaf and a muscle all contain living cells that respire. Plants respire in darkness as well as in light. Respiration releases energy already stored chemically in nutrients; it does not create energy. Oxygen reaches human tissues through gas exchange and circulation, but the release of energy happens within cells.',SY(20,'3.10.1'))
C('3.10.1-01','DEF','Define aerobic respiration.','The chemical reactions in cells that use oxygen to break down nutrient molecules to release energy.',['1 mark: the definition means chemical reactions in cells that break down nutrient molecules to release energy.', '1 mark: the answer must include that oxygen is used.'])
E('3.10.1-02','The word equation',['The word equation is glucose + oxygen → carbon dioxide + water.', 'Energy is released during aerobic respiration; it is not a material product to balance as atoms.'],'Read the arrow as “react to form”. Glucose is the nutrient that is respired and oxygen is the second reactant. Carbon dioxide leaves the body through the lungs; water can be used in cells or excreted. Overall this is the reverse of the photosynthesis equation, and plants carry out both processes: photosynthesis only in the light, respiration all the time.',S('7.4 Oxidative Phosphorylation'))
C('3.10.1-02','FEATURE','State the word equation for aerobic respiration.','Glucose + oxygen → carbon dioxide + water; energy is released.',['1 mark: names glucose and oxygen as the reactants and carbon dioxide and water as the products; mentioning energy is allowed but earns nothing extra.'])
C('3.10.1-02','MISCON','A student writes the word equation for aerobic respiration using the same two reactants as photosynthesis. Explain the error and give the correct word equation.','Carbon dioxide and water are the reactants of photosynthesis; in aerobic respiration they are the products. The correct equation is glucose + oxygen → carbon dioxide + water.',['1 mark: names the mistake: carbon dioxide and water are the reactants of photosynthesis, but they are the products of aerobic respiration.', '1 mark: gives the correct equation instead, with glucose and oxygen as reactants: glucose + oxygen → carbon dioxide + water.'])
E('3.10.1-03','The balanced equation',['The balanced equation is C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.', 'The equation has six carbon atoms, twelve hydrogen atoms and eighteen oxygen atoms on each side.'],'Coefficients multiply whole molecules. Check the balance atom by atom. Carbon: 6 in glucose and 6 × 1 in carbon dioxide. Hydrogen: 12 in glucose and 6 × 2 in water. Oxygen: 6 in glucose plus 6 × 2 = 12 from the oxygen molecules gives 18, and 6 × 2 in carbon dioxide plus 6 × 1 in water also gives 18. To balance an equation change only the large numbers in front of formulae; the small numbers inside a formula are fixed by what the substance is.',S('7.4 Oxidative Phosphorylation'))
C('3.10.1-03','FEATURE','State the balanced molecular equation for aerobic respiration.','C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.',['1 mark: one point for the balanced equation C6H12O6 + 6O2 → 6CO2 + 6H2O, with every formula and coefficient correct.'])
E('3.10.1-04','Uses of released energy',['Muscle contraction, active transport and synthesis of large molecules require energy released by respiration.','Respiration also contributes heat needed to maintain human body temperature.'],'Active transport moves particles against a concentration gradient. Building proteins supports growth and repair. Energy use continues during rest: the heart contracts, breathing muscles work and cells maintain their contents. Increased muscular activity increases energy demand, so respiration and delivery of oxygen must increase.',S('7.1 Energy in Living Systems'))
C('3.10.1-04','FEATURE','State one cellular use of energy released by respiration in humans.','Active transport across cell membranes.',['1 mark: names one valid use of the energy, such as active transport, muscle contraction, building large molecules or keeping the body warm.'])
E('3.10.1-05','Measuring seed oxygen uptake',['A respirometer can measure oxygen uptake when carbon dioxide produced by seeds is absorbed separately.','A volume-matched non-living control helps distinguish respiration from changes caused by temperature or pressure.'],'Use a sealed respirometer with germinating seeds and a narrow graduated tube containing a marker droplet. A carbon dioxide absorbent, separated from the seeds by a barrier, removes released carbon dioxide. As oxygen is consumed, gas volume falls and the droplet moves towards the seed chamber. A teacher handles the corrosive absorbent and checks airtight connections. Use a water bath, allow equilibration before closing the apparatus, then read movement over a measured time. A live-seed chamber and a control containing an equal volume of glass beads or boiled seeds should be compared at each temperature. Record direction and distance, not just whether a bubble moves. Repeat with fresh equivalent samples; divide corrected volume change by time and seed mass if rates per gram are needed.')
C('3.10.1-05','SYNTH','Describe a complete investigation, using a respirometer, to show that germinating seeds take up oxygen.','Compare living germinating seeds with the same volume of boiled (dead) seeds or glass beads. Measure the distance the coloured droplet moves towards the seeds in a set time. Keep the temperature the same by standing both tubes in the same water bath. Put a carbon dioxide absorbent, such as soda lime, in each tube behind a gauze, so that droplet movement shows oxygen uptake. Repeat with fresh seeds and calculate a mean distance.',['1 mark: changes the independent variable: living germinating seeds compared with boiled seeds or glass beads of the same volume.', '1 mark: measures the dependent variable: the distance the droplet moves (or the volume of gas taken up) in a set time.', '1 mark: keeps one named variable the same, such as temperature (in a water bath) or the volume of seeds.', '1 mark: uses a carbon dioxide absorbent in each tube, so the droplet moves only because oxygen is used.', '1 mark: repeats the readings and calculates a mean.'])
C('3.10.1-05','LIM','Suggest a limitation of a leaking seed respirometer and a linked improvement.','Outside air leaks in and replaces the oxygen used, so oxygen uptake is underestimated. Seal the joints and test for leaks before taking readings.',['1 mark: explains the problem that air leaking in replaces the oxygen used, so the uptake is underestimated.', '1 mark: suggests the improvement of sealing the joints and checking for leaks before readings are taken.'])
C('3.10.1-05','APP','In 5 min the droplet in a seed respirometer moves 9 mm towards the chamber, while the droplet in a control tube containing glass beads moves 3 mm the same way. Suggest the movement caused by oxygen uptake of the seeds and why the control reading is used.','The movement caused by the seeds is 9 - 3 = 6 mm in 5 min. The control has no living seeds, so its movement is caused by changes in temperature or pressure, not by respiration.',['1 mark: subtracts the control reading from the seed reading: 9 mm − 3 mm = 6 mm in 5 min.', '1 mark: explains that the control has no living seeds, so this 3 mm is caused by temperature or pressure changes, not respiration.'])
E('3.10.1-06','Temperature and respiration rate',['Respiration rate can be compared at different temperatures using equal masses of equivalent germinating seeds.', 'A rise in temperature can increase respiration until high temperatures impair the enzymes or damage cells.'],'For a temperature series, use separate comparable samples at 15, 25 and 35 °C rather than repeatedly heating one sample for different times. Read the bath thermometer rather than assuming its setting is the seed temperature. Allow each apparatus to equilibrate. An illustrative corrected oxygen uptake is 0.12 cm³ in 4 min: rate = 0.12 ÷ 4 = 0.03 cm³/min. A faster rate at 25 °C than at 15 °C supports a temperature effect over that interval. Rates do not keep rising: above the optimum temperature enzymes are damaged and the rate falls. Take readings before the oxygen in the sealed chamber becomes limiting. The same species, seed mass, hydration and germination stage reduce alternative explanations.')
C('3.10.1-06','SYNTH','Describe an experiment to find out how temperature changes the respiration of germinating seeds, using at least three temperatures.','Change the temperature using water baths at three or more values, such as 15, 25 and 35 °C. Measure the oxygen taken up per minute from the droplet movement. Keep the seed species, mass and stage of germination the same. Leave each respirometer in its bath for several minutes to reach the temperature before timing. Repeat at each temperature and compare the mean rates.',['1 mark: changes the independent variable: temperature, using water baths at three or more values.', '1 mark: measures the dependent variable: the oxygen taken up (droplet distance) per minute.', '1 mark: keeps one named variable the same, such as seed species, mass or stage of germination.', '1 mark: gives one workable detail of method, such as leaving the apparatus to reach the bath temperature before timing, or using a carbon dioxide absorbent.', '1 mark: repeats at each temperature and compares mean rates.'])
C('3.10.1-06','LIM','Suggest why comparing dry seeds at 15 °C with germinating seeds at 30 °C cannot isolate a temperature effect, and give an improvement.','Dry seeds respire much more slowly than germinating seeds at any temperature, so a difference could be caused by germination, not temperature. Use germinating seeds at the same stage and of equal mass at both temperatures.',['1 mark: explains the problem that dry seeds respire far more slowly at any temperature, so the difference could be due to germination rather than temperature.', '1 mark: suggests the improvement of using equally germinated seeds of the same mass at both temperatures.'])
C('3.10.1-06','APP','Suggest what can be concluded from corrected seed oxygen uptake rates of 0.02, 0.05 and 0.03 cm³/min at 15, 25 and 45 °C respectively.','The highest measured rate is at 25 °C. The fall at 45 °C is consistent with heat damaging the enzymes, but three values cannot show exactly where the optimum lies.',['1 mark: picks out the highest rate in this set, 0.05 cm³/min at 25 °C.', '1 mark: explains that the fall at 45 °C fits heat damaging the enzymes, so the optimum lies between 15 °C and 45 °C but its exact value is not known.'])

E('3.10.2-01','Anaerobic respiration',['Anaerobic respiration is the chemical reactions in cells that break down nutrient molecules to release a relatively small amount of energy, in the absence of oxygen.', 'The products depend on the organism: human muscles form lactic acid, whereas yeast forms ethanol and carbon dioxide.'],'The term describes the chemistry inside cells, not breathing. A muscle may use anaerobic energy release when its oxygen supply cannot meet its demand, even while the person is breathing hard. Less usable energy is transferred per glucose molecule than during aerobic respiration because glucose is only partly broken down.',SY(20,'3.10.2'))
C('3.10.2-01','DEF','Define anaerobic respiration.','The chemical reactions in cells that break down nutrient molecules to release a relatively small amount of energy, in the absence of oxygen.',['1 mark: the definition means chemical reactions in cells that break down nutrient molecules without oxygen.', '1 mark: the answer must include that only a relatively small amount of energy is released.'])
E('3.10.2-02','Anaerobic energy release in muscles',['The muscle word equation is glucose → lactic acid.', 'This process releases some energy without consuming oxygen in the reaction.'],'Muscle anaerobic respiration forms lactic acid only; no carbon dioxide is made in this pathway. During strenuous exercise muscles can use this pathway alongside aerobic respiration. The product differs from that of yeast, so name the organism or tissue when giving an anaerobic equation.',S('7.5 Metabolism without Oxygen'))
C('3.10.2-02','FEATURE','State the word equation for anaerobic respiration in human muscle.','Glucose → lactic acid; a small amount of energy is released.',['1 mark: names glucose as the reactant and lactic acid as the only product; energy released may be added but earns nothing extra.'])
E('3.10.2-03','Anaerobic energy release in yeast',['The yeast equation is C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂.','Yeast converts glucose into ethanol and carbon dioxide during alcoholic fermentation.'],'Count six carbon atoms on each side: four in the two ethanol molecules and two in carbon dioxide. The hydrogen and oxygen atoms balance too. Oxygen is not a reactant in this equation. The carbon dioxide can inflate dough, while ethanol is the relevant retained product in brewing.',S('7.5 Metabolism without Oxygen'))
C('3.10.2-03','FEATURE','State the balanced chemical equation for anaerobic respiration in yeast.','C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂.',['1 mark: one point for the balanced equation C6H12O6 → 2C2H5OH + 2CO2, with every formula and coefficient correct.'])
E('3.10.2-04','During strenuous activity',['When muscular energy demand outpaces oxygen delivery, anaerobic breakdown of glucose increases.', 'Lactic acid accumulates when its production exceeds its removal.'],'This gives muscles an additional rapid source of energy for a limited period. Lactic acid is carried away in blood, and its concentration reflects both production and removal. Lactic acid build-up is one factor in muscle fatigue, alongside others, and soreness a day or two later is a separate effect. The build-up explains why breathing and heart rate stay high after intense activity and why recovery is needed.',S('7.5 Metabolism without Oxygen'))
C('3.10.2-04','PROC','Describe how strenuous exercise leads to lactic acid accumulation in muscle.','The muscles need energy faster than oxygen can be delivered, so more glucose is broken down anaerobically. Lactic acid is produced faster than the blood removes it, so it builds up.',['1 mark: first, the muscles need energy faster than oxygen can be delivered, so more glucose is broken down anaerobically.', '1 mark: then lactic acid is produced faster than the blood removes it, so it builds up in the muscle.'])
E('3.10.2-05','Recovery after intense exercise',['Lactic acid is transported from muscles in the blood, including to the liver.', 'During recovery, lactic acid is processed: some can be oxidised and some converted back into glucose.', 'Breathing and circulation remain elevated after strenuous exercise to support the oxygen and energy demands of recovery.'],'The traditional term oxygen debt refers to the additional oxygen needed after exercise. Blood first removes lactic acid from muscle; the liver then helps process it. Conversion back to glucose requires energy supplied by aerobic respiration. Lactic acid is not breathed out: it is carried away in blood and processed in the liver. Recovery also restores other conditions in muscle, so extra oxygen use is a rough guide to the amount of lactic acid processed, not an exact measure.')
C('3.10.2-05','PROC','Outline the removal of lactic acid during recovery from intense exercise.','Blood carries lactic acid away from the muscles to the liver. The liver converts some of it back to glucose. Extra oxygen taken in after exercise is used in aerobic respiration, which supplies the energy for this and oxidises some lactic acid.',['1 mark: first, blood carries lactic acid away from the muscles to the liver.', '1 mark: then the liver converts some lactic acid back to glucose.', '1 mark: extra oxygen is used after exercise, so aerobic respiration supplies the energy for this conversion (accept: so some lactic acid is oxidised).'])
C('3.10.2-05','MECH','Explain the sequence linking lactic acid removal with continued rapid breathing after intense exercise.','Blood carries lactic acid from muscle to the liver. The liver converts some of it back to glucose. That conversion needs energy from aerobic respiration, so extra oxygen is needed. Breathing therefore stays fast after exercise to deliver this oxygen.',['1 mark: blood carries lactic acid from the muscle to the liver.', '1 mark: the liver converts some lactic acid to glucose.', '1 mark: this conversion needs energy, which comes from aerobic respiration, so extra oxygen is needed.', '1 mark: the effect is that breathing stays fast after exercise to deliver this extra oxygen.'])
E('3.10.2-06','Brewing',['Yeast uses sugars anaerobically to produce ethanol and carbon dioxide.', 'Brewing retains ethanol in the liquid, with temperature controlled to keep yeast active.'],'A sugar-containing liquid is inoculated with yeast and kept under conditions that limit oxygen after growth has been established. Gas must be able to escape safely rather than building pressure in a sealed vessel. If yeast becomes too hot its enzymes are damaged; if too cold, production slows. Fermentation stops when the sugar is used up or when the ethanol concentration becomes high enough to damage the yeast cells.',S('7.5 Metabolism without Oxygen'))
C('3.10.2-06','FEATURE','Name the two products formed when yeast respires anaerobically during brewing and describe what happens to each.','Ethanol is formed and stays in the liquid. Carbon dioxide is formed and is released as a gas.',['1 mark: names ethanol as a product and says it stays in the liquid.', '1 mark: names carbon dioxide as the other product and says it is released as a gas.'])
C('3.10.2-06','WHY','Explain why oxygen is limited during the ethanol-producing stage of brewing.','Ethanol is made only when yeast respires without oxygen. If plenty of oxygen were present, yeast would respire aerobically and form carbon dioxide and water instead of ethanol.',['1 mark: ethanol is made only when yeast respires without oxygen, which is the reason oxygen is kept out.', '1 mark: with plenty of oxygen, yeast respires aerobically and forms carbon dioxide and water instead, so little ethanol is made.'])
E('3.10.2-07','Bread-making',['Carbon dioxide released by yeast becomes trapped in dough and makes it rise.', 'Baking expands trapped gas, sets the dough structure and kills the yeast.'],'The soft elastic dough holds bubbles. Ethanol is also produced while yeast ferments sugar, but much of it evaporates during baking; it is not what inflates the loaf. Warm conditions speed activity within a suitable range, whereas very hot water damages the yeast enzymes before the dough rises.',S('7.5 Metabolism without Oxygen'))
C('3.10.2-07','FEATURE','Describe how yeast helps bread dough rise.','Yeast releases carbon dioxide while breaking down sugars anaerobically. Bubbles trapped in the dough increase its volume.',['1 mark: names carbon dioxide as the gas that yeast releases when it respires sugar.', '1 mark: states that bubbles of this gas trapped in the dough make it expand.'])
C('3.10.2-07','WHY','Explain why carbon dioxide production matters in bread-making although ethanol is formed at the same time.','Carbon dioxide is a gas that forms bubbles trapped in the dough. The bubbles make the dough rise, whereas ethanol does not form trapped bubbles and mostly evaporates during baking.',['1 mark: the reason is that carbon dioxide is a gas, so it forms bubbles that are trapped in the dough.', '1 mark: the trapped bubbles make the dough rise, whereas ethanol does not form bubbles and mostly evaporates during baking.'])
E('3.10.2-08','Relative energy yield',['Aerobic respiration releases more usable energy per glucose molecule than anaerobic respiration.', 'Anaerobic products retain chemical energy because breakdown is incomplete.'],'Compare the same amount of glucose, not different quantities of food or different times. An organism that obtains much less energy per glucose must use glucose faster to sustain the same energy demand. It may still fail to meet the demand if glucose delivery or the rate of the pathway is limiting.',S('7.5 Metabolism without Oxygen'))
C('3.10.2-08','DIST','Distinguish aerobic and anaerobic respiration in terms of energy released from the same amount of glucose.','Aerobic respiration releases more usable energy, whereas anaerobic respiration releases relatively little because breakdown remains incomplete.',['1 mark: says that aerobic respiration releases more usable energy from the same amount of glucose.', '1 mark: says, in contrast, that anaerobic respiration releases much less because the glucose is only partly broken down.'])
C('3.10.2-08','APP','Suggest why a muscle must consume glucose faster if its energy supply shifts from aerobic to anaerobic respiration but its energy demand stays unchanged.','Anaerobic respiration releases much less energy from each glucose molecule. More glucose must therefore be broken down each minute to supply the same energy.',['1 mark: states that anaerobic respiration releases much less energy from each glucose molecule.', '1 mark: so to meet the same energy demand in this muscle, more glucose must be broken down each minute.'])
E('3.10.2-09','Testing yeast gas production',['Carbon dioxide from anaerobic yeast respiration can be collected and identified using limewater.', 'A boiled-yeast control helps test whether gas production requires living yeast.'],'For a school investigation, cool boiled glucose solution to remove much dissolved oxygen, add yeast, and cover the liquid with a thin oil layer. Fit a delivery tube to a gas collector without sealing the gas outlet. Keep a modest constant temperature in a water bath. Count gas volume over a fixed time rather than relying on irregular bubble sizes. Test a sample of gas with limewater; cloudiness supports identification as carbon dioxide. Compare active yeast with boiled yeast under matching conditions. Because a little oxygen may remain, describe the conditions as oxygen-limited; the preparation is designed to favour anaerobic respiration.')
C('3.10.2-09','SYNTH','Yeast is mixed with boiled and cooled glucose solution and covered with a layer of oil to limit oxygen. Describe a complete investigation, using this set-up, to show that living yeast produces carbon dioxide.','Compare living yeast with boiled (dead) yeast. Measure the volume of gas collected in a gas syringe in a fixed time. Keep the glucose concentration, yeast mass and temperature the same, using a water bath. Bubble the gas through limewater: it turns cloudy if the gas is carbon dioxide. Repeat each treatment and calculate a mean volume.',['1 mark: changes the independent variable: living yeast compared with boiled yeast.', '1 mark: measures the dependent variable: the volume of gas collected in a fixed time.', '1 mark: keeps any two of glucose concentration, yeast mass and temperature the same.', '1 mark: passes the gas through limewater, which turns cloudy if it is carbon dioxide.', '1 mark: repeats each treatment and calculates a mean.'])
C('3.10.2-09','LIM','Suggest a limitation of counting bubbles to compare gas production by yeast and a linked improvement.','Bubbles differ in size, so counting them is an inaccurate measure of gas volume. Collect the gas in a gas syringe or measuring cylinder and read its volume over the same time instead.',['1 mark: explains the problem that bubbles differ in size, so a count is an inaccurate measure of gas volume.', '1 mark: suggests the improvement of collecting the gas in a gas syringe or measuring cylinder and reading its volume over the same time.'])
C('3.10.2-09','APP','Suggest a conclusion from an oxygen-limited yeast experiment: live yeast gives 14 cm³ gas in 8 min, boiled yeast gives 0 cm³, and the live-yeast gas turns limewater cloudy.','Only living yeast produced gas, and the cloudy limewater shows the gas is carbon dioxide, so living yeast produces carbon dioxide in these conditions.',['1 mark: 14 cm³ from live yeast and none from boiled yeast shows that only living yeast produced the gas.', '1 mark: the cloudy limewater shows this gas is carbon dioxide, so living yeast produced carbon dioxide.'])

E('3.11-01','Deamination',['Deamination is the removal of the nitrogen-containing part of amino acids to form urea.', 'Urea is formed in the liver and carried in the blood to the kidneys for excretion.'],'Protein eaten beyond the body’s needs is digested to amino acids, and the body cannot store the excess. In the liver the nitrogen-containing part of each excess amino acid is removed; the rest of the molecule can be respired for energy or converted to carbohydrate or fat. Urea is a waste product of metabolism, so its removal is excretion. Egestion, by contrast, removes undigested food that was never absorbed.',SY(21,'3.11'))
C('3.11-01','DEF','Define deamination.','The removal of the nitrogen-containing part of amino acids to form urea.',['1 mark: the definition means removal of the nitrogen-containing part of amino acids.', '1 mark: the answer must include that urea is formed.'])
E('3.11-02','Liver formation of urea',['The liver removes nitrogen-containing groups from excess amino acids.', 'Their nitrogen is incorporated into urea, which is less toxic than ammonia and can be transported for excretion.'],'Protein digestion first supplies amino acids, which cells use to make their own proteins. Deamination of the excess releases the nitrogen-containing part as ammonia, which is toxic, and the liver converts it to urea. The kidneys then filter urea out of the blood. Urea is a waste product, not a digestive enzyme, and it is not made from bile.',S('41.4 Nitrogenous Wastes'))
C('3.11-02','PROC','Describe how the liver contributes to the formation and removal of urea.','The liver removes the nitrogen-containing part of excess amino acids and turns it into urea. Blood carries the urea to the kidneys, which remove it in urine.',['1 mark: first, the liver removes the nitrogen-containing part of excess amino acids and turns it into urea.', '1 mark: then the blood carries the urea to the kidneys, so it is removed in urine.'])
C('3.11-02','MISCON','A student says that the liver removes nitrogen waste by making bile. Explain the error.','The liver gets rid of nitrogen by making urea from excess amino acids, and blood carries the urea to the kidneys. Bile is a different liver product: it goes into the small intestine and helps fat digestion.',['1 mark: states that the liver gets rid of nitrogen by making urea from excess amino acids, not bile.', '1 mark: urea is carried in the blood to the kidneys, whereas bile goes to the small intestine to help digest fat, so the student has confused the two.'])
E('3.11-03','Breaking down substances in the liver',['The liver chemically changes alcohol, many drugs and hormones.', 'Hormone breakdown helps prevent a signal continuing indefinitely after secretion changes.'],'Breakdown often converts a substance into forms that can be processed further or excreted. Some products are still harmful, and excessive alcohol can damage liver cells. Hormones such as adrenaline and insulin are broken down in the liver after they have acted, so their effects wear off. The effect of an individual medicine depends on its own properties.',None)
C('3.11-03','FEATURE','Describe two kinds of substances broken down by the liver.','The liver breaks down alcohol and many drugs. It also breaks down hormones after they have acted.',['1 mark: names one kind of substance broken down in the liver, such as alcohol or drugs.', '1 mark: names a second kind, such as hormones, after they have acted.'])
E('3.11-04','The urinary route',['Ureters carry urine from the kidneys to the bladder.', 'The bladder stores urine before it passes out through the urethra.'],'Urine is made in the two kidneys. It flows down a ureter from each kidney to the bladder, where it is stored. When the bladder is emptied, urine leaves the body through the urethra. There are therefore two ureters but only one bladder and one urethra. On a diagram, identify the tubes by where they start and end, not by their names or shapes: a ureter links a kidney to the bladder; the urethra starts at the bladder and opens outside the body. Only urine, not blood, flows along these tubes.',S('41.2 The Kidneys and Osmoregulatory Organs'))
C('3.11-04','FEATURE','Fig. VIS-6116-3.11-04 is a diagram of the human urinary system with each part marked by a letter. Identify the ureters, the bladder and the urethra from their positions and connections.','Ureters: the pair of tubes joining the kidneys to the bladder. Bladder: the sac that stores urine. Urethra: the single tube leading from the bladder to the outside of the body.',['Award 2 marks if the ureters (the pair of tubes joining the kidneys to the bladder), the bladder (the storage sac) and the urethra (the tube from the bladder to the outside) are all named correctly, and 1 mark if exactly two are named correctly.'],True)
E('3.11-05','Kidney functions',['Kidneys remove urea and excess water from blood into urine.', 'Glucose and some salts are reabsorbed into the blood rather than lost with the urine.'],'Excretion removes the waste products of metabolism. Glucose remains a useful nutrient; retaining it avoids wasting an energy source. Salt and water retention help keep the internal environment within a suitable range. Urine normally contains urea, water and salts, but glucose is normally recovered. Glucose in urine can mean blood glucose was very high, as in untreated diabetes (3.14).',S('41.2 The Kidneys and Osmoregulatory Organs'))
C('3.11-05','FEATURE','Describe two functions of the kidneys concerning urea and glucose.','They remove urea from blood into urine. They reabsorb glucose into blood.',['1 mark: names removal of urea (with excess water) from the blood into urine as one function.', '1 mark: names reabsorption of glucose back into the blood as the second function.'])
C('3.11-05','WHY','Explain why reabsorbing glucose in the kidneys is useful.','Glucose is a useful nutrient, not a waste product. Returning it to the blood keeps a source of energy for respiration in cells.',['1 mark: the reason is that glucose is a useful nutrient, not a waste product.', '1 mark: returning it to the blood keeps glucose available for respiration in cells, so that this energy source is not lost in urine.'])
E('3.11-06','Dialysis',['Dialysis allows small dissolved substances to diffuse across a partially permeable membrane between blood and dialysis fluid.', 'Blood cells and large proteins remain in the blood, while urea diffuses into fluid with little or no urea.', 'Suitable glucose and salt concentrations in dialysis fluid limit unwanted net loss of useful substances.'],'Blood passes along one side of a thin membrane while dialysis fluid flows on the other. Blood and dialysis fluid never mix; only small molecules cross. Fresh dialysis fluid keeps a urea concentration gradient, so urea keeps diffusing out. Because glucose concentrations are matched, there is little net diffusion of glucose, although individual molecules can move both ways. Excess water can also be removed under controlled conditions. A kidney machine supports patients with severe loss of kidney function but needs repeated sessions; it does not repair the kidneys.',None)
C('3.11-06','FEATURE','Outline how a dialysis machine removes urea while retaining blood cells and limiting glucose loss.','Urea diffuses through a partially permeable membrane into dialysis fluid that contains no urea. Blood cells are too large to cross. The fluid has the same glucose concentration as normal blood, so there is no net loss of glucose.',['1 mark: names diffusion of urea through the partially permeable membrane into dialysis fluid that contains no urea.', '1 mark: blood cells and large proteins are too large to pass through the membrane, so they stay in the blood.', '1 mark: the dialysis fluid has the same glucose concentration as normal blood, so there is no net loss of glucose.'])
E('3.11-07','Transplantation and dialysis',['A functioning transplanted kidney can provide continuous waste removal and freedom from repeated dialysis sessions.', 'Transplantation involves surgery, donor matching and possible rejection; medicines that suppress immunity can increase infection risk.'],'Dialysis is available without a donor organ and avoids transplant surgery, but repeated treatment takes time and can restrict daily routines and diet. A transplant may offer long-term benefit but is not guaranteed to last permanently. Which treatment suits a patient depends on their health, on donor availability and on access to treatment.',None)
C('3.11-07','EVAL','Discuss one advantage and one disadvantage of a kidney transplant compared with repeated dialysis, and give an overall judgement.','A successful transplant can free a person from repeated dialysis sessions. Surgery and rejection remain risks. Overall it can offer long-term benefit when a suitable kidney and continuing clinical care are available.',['1 mark: gives one advantage, such as freedom from repeated dialysis sessions.', '1 mark: gives one disadvantage or risk, such as surgery, rejection or the need for immune-suppressing drugs.', '1 mark: gives an overall judgement that weighs the two, for example that a transplant is better when a suitable kidney is available.'])
C('3.11-07','APP','Suggest why a transplant cannot yet replace dialysis for a patient who has no compatible donor and must still have urea removed from the blood regularly.','A kidney from a donor who is not compatible would be rejected by the patient’s immune system, so a transplant cannot be done yet. Dialysis must continue to remove urea from the blood while the patient waits for a matching kidney.',['1 mark: a kidney that is not compatible would be rejected by this patient’s immune system.', '1 mark: so dialysis must continue to remove urea from the blood while the patient waits for a matching kidney.'])
E('3.11-08','A model membrane separation',['Visking tubing can retain starch while allowing smaller glucose molecules or ions to pass.','Testing samples inside and outside the tubing distinguishes movement of a solute from movement of water.'],'Soak tubing, tie one end, add glucose and starch solution, then close it and rinse the outside carefully. Suspend it in water. Test outside samples at the start and after a fixed interval using iodine for starch and Benedict’s reagent in a hot-water bath for reducing sugar. A positive sugar test outside with a negative starch test supports selective passage. For sodium chloride and starch, use a fresh bag containing that mixture. After the set interval, test one outside sample with iodine and another with silver nitrate solution provided by the teacher: a white precipitate shows that chloride ions from the salt have passed out, while a negative iodine test shows the starch stayed inside. Use eye protection and never taste samples. Testing the outside water at the start as well shows that any positive result later is due to passage through the tubing, not spillage. Visking tubing behaves like the membrane in a kidney machine: small molecules and ions pass through it, large molecules such as starch and proteins do not.')
C('3.11-08','PROC','A mixture of glucose and starch solutions is placed in Visking tubing, which is rinsed and stood in a beaker of water. Identify the two tests carried out on the water outside after 30 minutes and the result of each that shows the mixture has been separated.','Benedict’s test: a sample heated with Benedict’s reagent in a hot-water bath turns from blue to orange-red, so glucose has passed out of the tubing. Iodine test: a second sample stays orange-brown with iodine solution, so starch has stayed inside.',['1 mark: Benedict’s test step: a sample heated with Benedict’s reagent in a hot-water bath turns orange-red (accept green, yellow or brick-red), so glucose has passed out of the tubing.', '1 mark: iodine test step: a second sample stays orange-brown with iodine solution, so starch has stayed inside the tubing.'])
C('3.11-08','WHY','Explain why the outside of filled Visking tubing is rinsed before testing its ability to separate glucose and starch.','Glucose or starch spilled on the outside would get into the water and give a positive test without crossing the membrane. Rinsing removes it, so a positive test shows passage through the tubing.',['1 mark: the reason is that glucose or starch spilled on the outside of the tubing would get into the water.', '1 mark: this would give a positive test without anything crossing the membrane, so rinsing makes sure a positive result comes from passage through the tubing.'])

E('3.12-01','Plant growth substances',['Plant growth substances are chemicals that affect the activities of particular cells and organs.','Auxins are plant growth substances involved in coordinating growth responses.'],'A plant has no nervous system, but chemicals can carry information and alter how cells grow. The same chemical need not have the same effect in every organ: response depends on concentration and tissue sensitivity. This helps explain why roots and shoots bend differently after being placed horizontally. Growth substances are made in one region, such as a shoot tip, and move to other cells where they act, and they are effective in very small amounts. In this way a plant coordinates its growth with the direction of light and of gravity.',SY(21,'3.12'))
C('3.12-01','DEF','Define plant growth substances.','Chemicals that affect the activities of particular cells and organs.',['1 mark: the definition means chemicals (substances).', '1 mark: the answer must include that they affect the activities of particular cells and organs.'])
E('3.12-02','Gravitropism',['Gravitropism is a response in which parts of a plant grow towards or away from gravity.', 'Roots commonly show positive gravitropism, while shoots commonly show negative gravitropism.'],'Positive means growth towards the stimulus, not a beneficial response. A horizontally placed seedling can develop a downward-curving root and an upward-curving shoot. The growing region bends over time because opposite sides elongate at different rates. Gravitropism helps a germinating seed send its root down into the soil and its shoot up towards the light. It is a directional growth response, not a rapid movement by muscle.',SY(21,'3.12'))
C('3.12-02','DEF','Define gravitropism.','A response in which parts of a plant grow towards or away from gravity.',['1 mark: the definition means a response in which parts of a plant grow towards or away from a stimulus.', '1 mark: the answer must include that the stimulus is gravity.'])
E('3.12-03','Phototropism',['Phototropism is a response in which parts of a plant grow towards or away from the direction from which light is coming.', 'Shoots commonly show positive phototropism by bending towards one-sided light.'],'Growth towards light can position leaves where light is available for photosynthesis. Uniform illumination does not give a directional cue, whereas light from one side does. In darkness shoots grow long and pale without bending in any set direction.',SY(21,'3.12'))
C('3.12-03','DEF','Define phototropism.','A response in which parts of a plant grow towards or away from the direction from which light is coming.',['1 mark: the definition means a response in which parts of a plant grow towards or away from a stimulus.', '1 mark: the answer must include that the stimulus is the direction from which light is coming.'])
E('3.12-04','Auxin and growth',['Auxin made near a shoot tip can alter elongation of cells behind the tip.', 'Unequal auxin distribution can produce unequal elongation and bend a growing organ.'],'If two sides of a shoot elongate equally, the organ becomes longer without curving. If one side becomes longer, it forms the outside of a bend and the tip turns towards the shorter side. Classic evidence comes from shoot tips. If the tip is removed, the shoot no longer bends towards one-sided light. If the tip is covered with an opaque cap, bending stops too, but if only the region below the tip is covered, bending still happens. This shows that the tip detects the light and sends a chemical signal, auxin, to the region behind it where cells elongate. Auxin is a chemical regulator, not food or a source of energy; cells still need nutrients, water and respiration to grow.',S('30.6 Plant Sensory Systems and Responses'))
C('3.12-04','FEATURE','Describe two features of auxin control of shoot growth.','Auxin is produced near the shoot tip. It regulates elongation of cells behind the tip.',['1 mark: names the shoot tip as where auxin is made.', '1 mark: names elongation of cells behind the tip as what auxin controls.'])
E('3.12-05','Synthetic growth substances as weedkillers',['Some synthetic plant growth substances disrupt growth when supplied in high concentrations.', 'Selective herbicides can affect broad-leaved weeds more than grasses at the intended dose.'],'Excess stimulation disrupts coordinated growth and can kill susceptible plants. Weedkillers of this kind are used on lawns and cereal crops: at the recommended dose they kill broad-leaved weeds such as dandelions, while grasses and cereals are largely unaffected. Selectivity is a difference in sensitivity between the plants, so it depends on the dose, the plant species and the conditions of application.',S('30.6 Plant Sensory Systems and Responses'))
C('3.12-05','FEATURE','Describe how an auxin-like selective weedkiller affects susceptible plants.','It disrupts normal coordinated growth. Susceptible weeds may grow abnormally and die.',['1 mark: names disruption of normal coordinated growth as the effect of the weedkiller.', '1 mark: names abnormal growth followed by death of the susceptible weeds as the outcome.'])
C('3.12-05','WHY','Explain why a selective auxin-like weedkiller can remove broad-leaved weeds from a grass crop at a suitable dose.','Broad-leaved weeds are more sensitive to the weedkiller than grasses. At the dose used their growth is disrupted and they die, while the grass crop is largely unaffected.',['1 mark: the reason is that broad-leaved weeds are more sensitive to the weedkiller than grasses.', '1 mark: at the dose used the growth of the weeds is disrupted so they die, while the grass crop is largely unaffected.'])
E('3.12-06','Two directional responses',['Gravitropism responds to the direction of gravity.','Phototropism responds to the direction of light.'],'Both are growth responses and can occur together. A root bending downward in a dark container demonstrates a gravity response without directional light. A shoot bending towards a side window may respond to light even though gravity is also present. Two examples show how to separate them. A seedling lying on its side in a dark box can respond only to gravity, so its root curves down and its shoot curves up. An upright seedling beside a window is not lying down, so a bend towards the glass is a light response. An experiment must change one cue at a time, otherwise the observed bend cannot be linked to its cause.',S('30.6 Plant Sensory Systems and Responses'))
C('3.12-06','DIST','Distinguish gravitropism from phototropism.','Gravitropism is directional growth in response to gravity, whereas phototropism is directional growth in response to light.',['1 mark: says that gravitropism is directional growth in response to gravity.', '1 mark: says, in contrast, that phototropism is directional growth in response to light.'])
E('3.12-07','Differential growth and bending',['In a shoot lit from one side, more auxin collects on the shaded side and promotes greater elongation there, bending the shoot towards light.', 'In a horizontal shoot, greater auxin on the lower side promotes greater elongation below, bending the shoot upwards.', 'In a horizontal root, the higher auxin concentration on the lower side inhibits elongation there, because roots are more sensitive to auxin than shoots, so the root bends downwards.'],'Follow the sequence: stimulus direction changes the distribution of auxin; opposite sides elongate by different amounts; the tip bends. The longer side is on the outside of the curve. Worked example: if the shaded side of a shoot elongates 4 mm while the lit side elongates 1 mm, the shaded side is 3 mm longer and the shoot curves towards the light. A build-up of auxin that speeds up growth in a shoot therefore slows it in a root, and the same stimulus bends the two organs in opposite directions. A horizontally placed seedling in darkness still bends in response to gravity. If a seedling is rotated slowly so that no side stays lower, the effect of gravity is averaged out and little curvature develops. A rotating seedling is still under gravity; it is simply not exposed to it from one side only.',S('30.6 Plant Sensory Systems and Responses'))
C('3.12-07','PROC','Explain why a young shoot bends towards light from one side.','More auxin collects on the shaded side, so cells there elongate more. The longer shaded side forms the outside of the curve, so the shoot bends towards the light.',['1 mark: first, more auxin collects on the shaded side, so cells there elongate more.', '1 mark: then the longer shaded side forms the outside of the curve, so the shoot bends towards the light.'])
C('3.12-07','MECH','Explain the contrasting auxin-mediated responses of a horizontally placed root and shoot to gravity.','Auxin collects on the lower side of both. In the shoot it causes more elongation on the lower side, so the shoot bends upwards. Roots are more sensitive to auxin, so in the root the same build-up inhibits elongation on the lower side. The upper side of the root grows more, so the root bends downwards.',['1 mark: auxin collects on the lower side of both the root and the shoot.', '1 mark: in the shoot, auxin causes more elongation on the lower side, so the shoot bends upwards.', '1 mark: roots are more sensitive to auxin, so in the root the same build-up inhibits elongation on the lower side.', '1 mark: the effect is that the upper side of the root grows more, so the root bends downwards.'])
C('3.12-07','APP','Explain the likely bend of a young shoot when a treatment makes its left side elongate 4 mm and its right side elongate 1 mm during the same period.','It bends towards the right. The left side grows 3 mm more, so it becomes the longer outside of the curve.',['1 mark: the left side grew 3 mm more than the right side in this period, so it is the longer side.', '1 mark: the longer side is on the outside of the curve, so the shoot bends towards the right.'])
E('3.12-08','Observing seedlings under different light conditions',['Seedlings under uniform light can grow without a consistent sideways phototropic bend.','Seedlings under one-sided light commonly curve towards it, whereas dark-grown seedlings may be elongated and pale.'],'Grow comparable seedlings for the same time with water, temperature and starting size matched. Photograph or draw each against a reference line at the start and end; record height, curvature direction and colour separately. Darkness can affect both colour and elongation, so a longer seedling is not necessarily a healthier or better photosynthesising one. Use several seedlings in each group because individuals differ. Interpretation should separate “light direction changed curvature” from “light availability changed colour or growth”. If a window also changes temperature, the experiment has an additional variable.')
C('3.12-08','PROC','Describe how to record the appearance of matched seedlings grown under uniform light, one-sided light and darkness.','After the same time, record the height and direction of bending of each seedling. Record the leaf colour of each group, looking at them all under the same lighting.',['1 mark: records the height and the direction of bending of each seedling after the same time.', '1 mark: records the leaf colour of each group under the same lighting, so the groups can be compared fairly; the two points can be given in any order.'])
C('3.12-08','LIM','Suggest a limitation of judging a light-growth experiment from one seedling per treatment and a linked improvement.','One seedling may differ from the others by chance, so a difference may not be caused by the light. Grow several matched seedlings in each treatment and compare the group pattern.',['1 mark: explains the problem that one seedling may differ from the others by chance, so a difference may not be caused by the light.', '1 mark: suggests the improvement of growing several matched seedlings per treatment and comparing the group pattern.'])
C('3.12-08','APP','Suggest an interpretation of these matched seedlings after four days: uniform light, green and upright; side light, green and bent towards the opening; darkness, pale and elongated.','The bend towards the opening shows a directional growth response to light. The pale, elongated seedlings in darkness show the effect of having no light at all, not growth towards a light source.',['1 mark: the side-lit seedlings bending towards the opening show a directional growth response to light.', '1 mark: the pale, elongated seedlings in darkness show the effect of having no light at all, so this is not growth towards a light source.'])
E('3.12-09','Investigating directional growth',['Directional growth experiments must separate light direction from gravity direction.','Replicated matched seedlings and recorded initial orientation make curvature evidence interpretable.'],'For phototropism, stand matched seedlings upright in boxes admitting equal light either from one side or uniformly. Keep temperature, water and duration equal; record shoot curvature from starting positions. For gravitropism, place germinated seeds horizontally on moist support in darkness, with roots and shoots free to grow. Compare with seedlings maintained in their normal upright orientation. A slowly rotating clinostat can be a further control if available. Record both root and shoot direction; do not infer one from the other. Keep support moist rather than submerged so oxygen remains available. Repeats test whether the pattern is consistent rather than the chance shape of one seedling.')
C('3.12-09','SYNTH','Describe a complete investigation of gravitropism in the roots and shoots of germinating seedlings.','Change the orientation: some seedlings horizontal, others upright. Measure the direction of curvature of roots and shoots after the same time. Keep the species, age, moisture and temperature the same. Keep all the seedlings in darkness so that light cannot give a direction. Repeat with several seedlings per orientation and compare the typical response.',['1 mark: changes the independent variable: the orientation of the seedlings (horizontal compared with upright).', '1 mark: measures the dependent variable: the direction (or angle) of curvature of roots and shoots after the same time.', '1 mark: keeps one named variable the same, such as species, age, moisture or temperature.', '1 mark: keeps all the seedlings in darkness so that light cannot give a direction.', '1 mark: repeats with several seedlings in each orientation and compares the typical result.'])
C('3.12-09','LIM','Suggest why leaving horizontal seedlings on a sunny windowsill weakens a gravitropism investigation and give an improvement.','One-sided light from the window also causes directional growth, so a bend cannot be put down to gravity alone. Grow the seedlings in darkness or uniform light.',['1 mark: explains the problem that one-sided light also causes directional (phototropic) growth, so a bend cannot be put down to gravity alone.', '1 mark: suggests the improvement of working in darkness or uniform light so only gravity gives a direction.'])
C('3.12-09','APP','Suggest what is supported when horizontal seedlings grown in darkness develop roots curving down and shoots curving up, while upright controls stay aligned vertically.','The bends support positive gravitropism in roots and negative gravitropism in shoots. Light direction cannot explain the pattern because the seedlings were grown in darkness.',['1 mark: roots curving down and shoots curving up in this result support positive gravitropism in roots and negative gravitropism in shoots.', '1 mark: the seedlings were in darkness, so light direction cannot explain the bending.'])

E('3.13.1-01','Neurones',['Sensory neurones carry impulses from receptors towards the central nervous system; motor neurones carry them from the central nervous system to effectors.', 'Relay neurones connect neurones within the central nervous system.'],'A sensory neurone has its cell body on a short side branch part-way along one long fibre; the fibre brings impulses from a receptor to the spinal cord. A motor neurone has its cell body at one end, with many short branches and one long axon that carries impulses out to a muscle or gland. A relay neurone is a short neurone inside the central nervous system that links sensory and motor neurones. The central nervous system is the brain and spinal cord. Textbook diagrams are simplified, so identify a neurone by where its cell body lies, how it branches and where its fibre leads, rather than by overall outline alone.',S('35.1 Neurons and Glial Cells'))
C('3.13.1-01','FEATURE','Fig. VIS-6116-3.13.1-01 is a diagram of three neurones, each marked with a letter. Identify the sensory neurone, the motor neurone and the relay neurone, using the position of the cell body and the pattern of branching.','Sensory neurone: the cell body lies on a side branch part-way along the long fibre. Motor neurone: the cell body is at one end, with short branches and a long axon leading out. Relay neurone: the short neurone with branches that lies within the central nervous system.',['Award 2 marks if the sensory neurone (cell body on a side branch of the long fibre), the motor neurone (cell body at one end, long axon) and the relay neurone (short, within the central nervous system) are all named correctly, and 1 mark if exactly two are named correctly.'],True)
E('3.13.1-02','Effectors',['Effectors carry out responses: muscles contract and glands secrete substances.', 'An effector receives signals after information about a stimulus has been processed.'],'Receptors detect stimuli, such as pressure on skin; they do not pull the hand away. The muscle is the effector in that response. A gland releasing a secretion is also an effector, even though its response is not a visible movement. Detection, coordination and response are three separate functions: receptor, coordinator, effector.',S('35.3 The Central Nervous System'))
C('3.13.1-02','FEATURE','Describe the responses of the two main kinds of effector.','Muscles contract. Glands release secretions.',['1 mark: names muscles contracting as the response of one kind of effector.', '1 mark: names glands secreting (releasing) substances as the response of the other kind.'])
E('3.13.1-03','Synapses',['A synapse is a junction between two neurones or between a neurone and an effector.','At a chemical synapse a signal crosses a small gap using a neurotransmitter.'],'The cells do not join into one continuous cell. Transmission along a neurone is an electrical impulse, whereas crossing the junction requires a chemical signal. The junction allows a signal to pass to an appropriate next cell.',SY(22,'3.13.1'))
C('3.13.1-03','DEF','Define a synapse.','A junction between two neurones or between a neurone and an effector.',['1 mark: the definition means a junction between two neurones.', '1 mark: the answer must include that it can also be a junction between a neurone and an effector.'])
E('3.13.1-04','Transmission across a synapse',['An impulse arriving at a neurone ending triggers release of neurotransmitter into the synaptic gap.', 'Neurotransmitter diffuses across and binds to receptors on the next cell, triggering its response when sufficient stimulation occurs.', 'Removal or breakdown of neurotransmitter helps stop continuing stimulation after release ceases.'],'The order is arrival, release, diffusion and receptor binding, followed by the next electrical impulse or an effector response. The impulse does not jump across the gap: a chemical carries the signal. Neurotransmitter is released from the sending side and the receptors are on the receiving side, so a chemical synapse normally passes signals in one direction only. The transmitter is then broken down or taken back up, which stops the receiving cell being stimulated continuously. A chemical that blocks release leaves the impulse arriving normally but stops the signal reaching the next cell. A chemical that blocks the receptors also stops the signal, but acts after the transmitter has been released.',S('35.2 How Neurons Communicate'))
C('3.13.1-04','PROC','Describe how a signal crosses a chemical synapse.','An arriving impulse causes neurotransmitter to be released. The transmitter diffuses across the gap and binds to receptors on the next cell, so a new impulse starts.',['1 mark: first, an impulse arriving at the end of the neurone causes neurotransmitter to be released.', '1 mark: then the neurotransmitter diffuses across the gap and binds to receptors on the next cell, so a new impulse starts.'])
C('3.13.1-04','MECH','Describe the complete sequence of transmission across a synapse between two neurones.','An impulse reaches the end of the first neurone and causes neurotransmitter to be released. The transmitter diffuses across the synaptic gap. It binds to receptors on the second neurone. A new impulse starts in the second neurone if enough transmitter binds.',['1 mark: an impulse arriving at the end of the first neurone causes neurotransmitter to be released.', '1 mark: the neurotransmitter diffuses across the synaptic gap.', '1 mark: it binds to receptors on the second neurone.', '1 mark: the effect is that a new impulse starts in the second neurone if enough transmitter binds.'])
C('3.13.1-04','APP','Explain why the second neurone stops responding when impulses still reach the end of the first neurone but a chemical stops neurotransmitter being released. The receptors are not affected.','The impulse is electrical and cannot cross the gap without neurotransmitter. With no transmitter binding, the receptors on the second neurone are not stimulated, so it does not respond.',['1 mark: the impulse is electrical and cannot cross the gap without neurotransmitter.', '1 mark: with no transmitter binding, the receptors on this second neurone are not stimulated, so no new impulse starts.'])
E('3.13.1-05','Alcohol and synaptic signalling',['Alcohol is a depressant that reduces the release of neurotransmitter at synapses, which slows synaptic transmission in the nervous system.', 'Slower transmission delays impulses along coordinating pathways, which impairs coordination and lengthens reaction time.'],'A synapse is a slow step in a pathway, because a chemical has to diffuse across the gap. Alcohol reduces the amount of neurotransmitter released when an impulse arrives, so less transmitter crosses the gap and the next neurone is stimulated more slowly, or not at all. When alcohol slows transmission at many synapses, every pathway that includes them takes longer to deliver its signal to an effector. A person who has been drinking therefore reacts more slowly to a hazard, and coordination, such as walking in a straight line, becomes poorer. Judgement and self-control also decline because the decision-making parts of the brain are affected.')
C('3.13.1-05','FEATURE','Describe two effects of alcohol on the nervous system.','Alcohol reduces the release of neurotransmitter, so synaptic transmission is slower. It also impairs coordination and judgement and lengthens reaction time.',['1 mark: names reduced neurotransmitter release, or slower synaptic transmission, as one effect of alcohol.', '1 mark: names impaired coordination, judgement or longer reaction times as a second effect.'])
C('3.13.1-05','WHY','Explain why slower synaptic transmission after drinking alcohol makes reactions slower.','Impulses take longer to cross the synapses on the pathway from receptor to effector. The time between the stimulus and the response is therefore longer.',['1 mark: the reason is that impulses take longer to cross each synapse on the pathway from receptor to effector.', '1 mark: so the time between the stimulus and the response is longer.'])
E('3.13.1-06','Voluntary and involuntary actions',['Voluntary actions involve conscious decisions, such as choosing to pick up a book.', 'Involuntary actions occur without a conscious decision to perform each response, such as pupil constriction in bright light.'],'An action can involve muscles without being voluntary. The key distinction is conscious control, not the organ used or how quick the movement is. Breathing is normally automatic but can also be controlled consciously for a short time, so some actions can be either kind.',S('35.3 The Central Nervous System'))
C('3.13.1-06','DIST','Distinguish a voluntary action from an involuntary action, giving one example of each.','A voluntary action follows a conscious decision, such as lifting a pen; an involuntary action occurs without that decision, such as pupil constriction.',['1 mark: says that a voluntary action follows a conscious decision, with a correct example such as lifting a pen.', '1 mark: says, in contrast, that an involuntary action happens without that decision, with a correct example such as pupil narrowing.'])
E('3.13.1-07','A simple spinal reflex arc',['In a simple withdrawal reflex, a sensory neurone carries an impulse from a receptor to the spinal cord.', 'A relay neurone passes the signal to a motor neurone, which carries an impulse to a muscle effector.', 'Contraction of the effector produces the withdrawal response before conscious consideration is needed.'],'A skin receptor detects a potentially damaging stimulus such as a sharp object. A sensory neurone carries the impulse into the spinal cord, where it crosses a synapse to a relay neurone and then another synapse to a motor neurone. The motor neurone carries the impulse to a muscle, which contracts. The reflex arc is therefore stimulus, receptor, coordinator (the spinal cord), effector, response. Impulses also pass up to the brain, so you become aware of the pain just after the hand has already moved. The arrows run one way, from receptor to effector, with no loop back to the receptor.',S('35.3 The Central Nervous System'))
C('3.13.1-07','PROC','Describe the route of a nerve impulse through a simple spinal reflex arc.','A sensory neurone carries the impulse from the receptor to the spinal cord, where a relay neurone passes it on. A motor neurone then carries it to the effector.',['1 mark: first, the sensory neurone carries the impulse from the receptor to the spinal cord, where a relay neurone passes it on.', '1 mark: then the motor neurone carries the impulse to the effector, so the response happens.'])
C('3.13.1-07','MECH','Describe the complete sequence that withdraws a hand from a painful stimulus in a simple spinal reflex.','A receptor starts an impulse in a sensory neurone. A relay neurone in the spinal cord passes the impulse to a motor neurone. The motor neurone carries it to a muscle, which contracts. The hand is pulled away.',['1 mark: the receptor starts an impulse in a sensory neurone.', '1 mark: a relay neurone in the spinal cord passes the impulse to a motor neurone.', '1 mark: the motor neurone carries the impulse to a muscle, which causes it to contract.', '1 mark: the effect is that the hand is pulled away.'])
E('3.13.1-08','Spinal-cord section drawing',['A transverse spinal-cord section has central grey matter surrounded by white matter.', 'A biological drawing records the visible arrangement with clear outlines, accurate proportions and precise labels.'],'In a transverse section the spinal cord is a roughly circular slice. The central grey matter is shaped like a butterfly or the letter H and is surrounded by paler white matter; a small central canal runs through the middle of the grey matter. To draw it, use a sharp pencil and a large space. Draw the outer boundary as one continuous line, then the grey matter inside it with the shape and relative size that you can see, not a memorised symbol. Do not shade or colour. Draw straight, uncrossed label lines that end exactly on the region named. A biological drawing earns marks for clear lines, accurate proportions and precise labels.',S('35.3 The Central Nervous System'))
C('3.13.1-08','FEATURE','Fig. VIS-6116-3.13.1-08 is a photomicrograph of a transverse section of the spinal cord. Draw a large labelled diagram of the section, labelling the grey matter, the white matter and the central canal.','A large drawing with clear, continuous, unshaded lines. The H-shaped or butterfly-shaped grey matter is in the centre, surrounded by white matter, with the small central canal in the middle of the grey matter. Straight label lines touch the grey matter, white matter and central canal.',['1 mark: the drawing is large, with clear continuous lines and no shading.', '1 mark: the grey matter is drawn H-shaped (or butterfly-shaped) in the centre, surrounded by white matter.', '1 mark: the central canal is shown in the middle of the grey matter.', '1 mark: the three parts are labelled, with straight label lines that touch the correct regions.'],True)
E('3.13.1-09','Reflex action',['A reflex action is a means of integrating and coordinating stimuli with responses of effectors.', 'Reflex responses are typically rapid and automatic, linking a detected stimulus to an appropriate effector response.'],'Integration means bringing the incoming information together into a coordinated response. The reflex arc is the neural route; the reflex action is the resulting coordinated response. A withdrawal reflex reduces contact with a damaging stimulus, and the pupil reflex regulates the light entering the eye.',SY(22,'3.13.1'))
C('3.13.1-09','DEF','Define a reflex action.','A means of integrating and coordinating stimuli with responses of effectors.',['1 mark: the definition means a way of integrating and coordinating stimuli.', '1 mark: the answer must include that this links the stimuli with the responses of effectors.'])
E('3.13.1-10','Sense organs',['Sense organs are groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals.','Receptor cells convert stimulation into signals carried towards the central nervous system.'],'Different receptors are suited to different kinds of stimulus. The eye detects light, the ear detects sound, and receptor cells in skin detect touch and temperature. Chemical receptors contribute to smell and taste. A sense organ includes supporting structures that help stimulation reach its receptors, but these supporting structures do not all detect the stimulus.',SY(22,'3.13.1'))
C('3.13.1-10','DEF','Define sense organs.','Groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals.',['1 mark: the definition means groups of receptor cells.', '1 mark: the answer must include that they respond to specific stimuli, such as light, sound, touch, temperature or chemicals.'])

# Individual eye structures retain distinct objective and claim traceability.
eye=[
('11','Cornea','The cornea is the transparent curved front surface of the eye.','It refracts incoming light, contributing much of the eye’s focusing power.','Light first enters the eye through the cornea. It is transparent so that light can pass through and curved so that it bends the light inwards. Most of the refraction in the eye happens at the cornea, but its shape is fixed, so it cannot adjust the focus for different distances. It lies in front of the iris and pupil; the lens is behind the pupil.','State the main optical function of the cornea.','It refracts incoming light towards a focus on the retina.','1 mark: names refraction (bending) of light as the main optical function of the cornea.'),
('12','Iris','The iris is the coloured ring surrounding the pupil.','Its circular and radial muscles alter pupil diameter and regulate the light entering the eye.','The iris is a ring of muscle tissue, brown, blue or green in colour, with the pupil as the opening at its centre. Circular muscles run around the pupil and radial muscles run outwards like spokes. Their action changes the diameter of the pupil and so the amount of light reaching the retina. The iris does not change the shape of the lens; the ciliary muscles do that.','State the function of the iris.','It regulates incoming light by changing pupil diameter.','1 mark: names control of the amount of light entering the eye by changing the size of the pupil.'),
('13','Pupil','The pupil is the opening within the iris.','Light passes through the pupil towards the lens and retina.','The pupil is the dark opening at the centre of the iris. Light passes through it to the lens and then to the retina. Under the same illumination a wider pupil admits more light than a narrower one. The pupil has no muscle of its own: the muscles of the iris change the size of the opening.','State the function of the pupil.','It allows light to enter the eye.','1 mark: names the function, that it lets light into the eye as an opening.'),
('14','Lens','The lens is a transparent structure behind the pupil.','It changes shape to adjust refraction and focus images of objects at different distances on the retina.','The lens lies behind the pupil. It is transparent and elastic and is held in place by suspensory ligaments. The cornea and the lens both refract light, but only the lens can change shape, so it provides the adjustable focusing. Changing the size of the pupil changes how much light enters, not where the light is focused.','State the function of the lens.','It refracts light to focus an image on the retina.','1 mark: names focusing of light on the retina by refraction as the function of the lens.'),
('15','Retina','The retina is the light-sensitive layer lining the back of the eye.','Its receptor cells respond to light and initiate nerve signals.','The retina lines the back of the eye and contains the light receptor cells, the rods and cones. A focused image on the retina stimulates these cells, which start nerve impulses. The retina is the layer on which the image forms; the optic nerve carries the signals away from the eye. When asked for the light-sensitive part of the eye, the answer is the retina, not the lens or the optic nerve.','State the function of the retina.','It detects light and initiates nerve signals.','1 mark: names detection of light, with nerve impulses started, as the function of the retina.'),
('16','Optic nerve','The optic nerve leaves the back of the eye and connects it with the brain.','It carries nerve impulses generated after retinal stimulation.','The optic nerve leaves the back of the eye and runs to the brain. The retina first converts light into nerve impulses, and the optic nerve carries those impulses to the brain, where the image is interpreted. Light itself does not travel along the nerve.','State the function of the optic nerve.','It carries nerve impulses from the eye towards the brain.','1 mark: names carrying of nerve impulses from the eye to the brain as the function of the optic nerve.'),
('17','Blind spot','The blind spot is the region where the optic nerve leaves the retina.','It has no rods or cones and therefore does not detect light.','The blind spot is the small region of the retina where the optic nerve leaves the eye. There are no rods or cones there, so light falling on it cannot be detected. You do not normally notice the gap because the brain fills it in, using information from the surrounding part of the image and from the other eye.','State why light falling on the blind spot is not detected there.','It contains no light receptor cells.','1 mark: names the reason, that there are no light receptor cells (rods and cones) at the point where the optic nerve leaves the eye.')]
for n,h,c1,c2,p,q,a,gd in eye:
    E('3.13.1-'+n,h,[c1,c2],p,S('36.5 Vision'))
    C('3.13.1-'+n,'FEATURE',q,a,[gd])
C('3.13.1-15','MISCON','Explain the error in identifying the lens as the light-sensitive layer at the back of the eye.','The retina is the light-sensitive layer lining the back of the eye. The lens is a transparent structure behind the pupil that focuses light onto the retina.',['1 mark: states that the retina, not the lens, is the light-sensitive layer at the back of the eye.', '1 mark: the lens is instead a transparent structure behind the pupil that focuses light onto the retina.'])
E('3.13.1-18','Pupil reflex',['In bright light, circular iris muscles contract and radial muscles relax, narrowing the pupil.', 'In dim light, radial iris muscles contract and circular muscles relax, widening the pupil.'],'These muscle groups work antagonistically: when one contracts the other relaxes. In bright light the circular muscles, which run around the pupil, contract and the radial muscles, which run outwards like spokes, relax, so the pupil narrows. A smaller pupil reduces the light entering and protects the light-sensitive retina. In dim light the radial muscles contract and the circular muscles relax, so a larger pupil admits more light. The pupil is an opening, so it cannot contract as a muscle does. The response changes how much light is admitted; it does not bring a near object into focus. Walking from a bright street into a dark cinema shows it: at first you see little, then the pupils widen and you see more.',None)
C('3.13.1-18','PROC','Explain how the pupil narrows in bright light.','The circular muscles of the iris contract while the radial muscles relax. The pupil becomes smaller, so less light reaches the retina.',['1 mark: first, the circular muscles of the iris contract and the radial muscles relax.', '1 mark: so the pupil becomes narrower and less light reaches the retina.'])
C('3.13.1-18','MECH','Explain the antagonistic muscle changes and effects when the eye moves from bright to dim light.','The radial muscles of the iris contract. The circular muscles relax. Because the two sets work antagonistically, this widens the pupil. More light then reaches the retina.',['1 mark: the radial muscles of the iris contract.', '1 mark: the circular muscles of the iris relax.', '1 mark: the two sets of muscles work antagonistically, which widens the pupil.', '1 mark: the effect is that more light enters the eye and reaches the retina.'])
C('3.13.1-18','APP','Explain why a pupil cannot narrow in bright light if the circular muscles of the iris cannot contract, although the radial muscles relax normally.','The pupil narrows only when the circular muscles contract. Relaxing the radial muscles alone does not pull the pupil smaller, so it stays wide.',['1 mark: narrowing of the pupil needs the circular muscles to contract.', '1 mark: relaxing the radial muscles alone does not pull this pupil smaller, so it stays wide.'])
C('3.13.1-18','MISCON','Explain the error in saying that ciliary muscles contract to make a pupil narrower in bright light.','The pupil is narrowed by the circular muscles of the iris contracting while the radial muscles relax. Ciliary muscles change the shape of the lens for focusing.',['1 mark: states that the pupil is narrowed by the circular muscles of the iris contracting, with the radial muscles relaxing.', '1 mark: the ciliary muscles instead change the shape of the lens for focusing, so the student has confused the two sets of muscles.'])
E('3.13.1-19','Accommodation for near objects',['For a near object, ciliary muscles contract and suspensory ligaments become less tense.', 'The lens becomes thicker and more curved, increasing refraction so the near object can be focused on the retina.'],'Light from a nearby point reaches the eye more divergent than light from a distant point. Stronger refraction is needed to focus it at the same distance behind the lens. Ciliary-muscle contraction reduces tension in the ligaments; it does not pull the lens flatter. The elastic lens rounds up when it is less stretched. Reading a book is a near-focus task, which is why the ciliary muscles tire after long periods of close work.',None)
C('3.13.1-19','PROC','Explain how the eye adjusts its lens for viewing a near object.','The ciliary muscles contract, so the suspensory ligaments slacken. The lens becomes thicker and refracts light more strongly.',['1 mark: first, the ciliary muscles contract, so the suspensory ligaments slacken.', '1 mark: then the lens becomes thicker (more curved), so light from the near object is refracted more strongly.'])
C('3.13.1-19','MECH','Explain the complete accommodation mechanism for a near object.','The ciliary muscles contract. The suspensory ligaments slacken. The elastic lens becomes thicker and more curved. Light is refracted more, so the near object is focused on the retina.',['1 mark: the ciliary muscles contract.', '1 mark: this makes the suspensory ligaments slacken, which lets the lens change shape.', '1 mark: the elastic lens becomes thicker and more curved.', '1 mark: the effect is that light is refracted more, so the near object is focused on the retina.'])
C('3.13.1-19','APP','Explain why an older person whose lens has become stiff cannot focus on a near object, even though the ciliary muscles contract and the suspensory ligaments slacken.','A stiff lens cannot become thicker and more curved, so it cannot refract light more. The near object is therefore not focused on the retina.',['1 mark: this stiff lens cannot become thicker and more curved when the ligaments slacken.', '1 mark: so light from the near object is not refracted enough to be focused on the retina.'])
C('3.13.1-19','MISCON','A student says that, to focus on a near object, the ciliary muscles relax. Explain the error and state what then happens to the suspensory ligaments and the lens.','Relaxed ciliary muscles are the condition for distant vision. For a near object the ciliary muscles contract, so the suspensory ligaments slacken and the elastic lens becomes thicker, refracting light more strongly.',['1 mark: names the mistake: relaxed ciliary muscles are for distant vision; for a near object they contract instead.', '1 mark: so the suspensory ligaments slacken and the lens becomes thicker, which refracts light more.'])
E('3.13.1-20','Accommodation for distant objects',['For a distant object, ciliary muscles relax and suspensory ligaments become more tense.', 'The lens is pulled thinner and flatter, reducing refraction to focus distant light on the retina.'],'Light rays from a distant point are nearly parallel when they arrive. They need less refraction than rays from a near point. Relaxed ciliary muscles allow the ring they form to widen, which tightens the ligaments and stretches the lens; the ligaments do not actively contract. Looking up from a book at a distant hill is a change from near focus to distant focus: the ciliary muscles relax and the lens becomes thinner.',None)
C('3.13.1-20','PROC','Explain how the eye adjusts its lens for a distant object.','The ciliary muscles relax, so the suspensory ligaments are pulled tight. The lens is stretched thinner and refracts light less.',['1 mark: first, the ciliary muscles relax, so the suspensory ligaments are pulled tight.', '1 mark: then the lens is stretched thinner, so light from the distant object is refracted less.'])
C('3.13.1-20','MECH','Explain the complete accommodation mechanism for a distant object.','The ciliary muscles relax. The suspensory ligaments become tight and pull on the lens. The lens becomes thinner and flatter. Light is refracted less, so the distant object is focused on the retina.',['1 mark: the ciliary muscles relax.', '1 mark: the suspensory ligaments become tight, which pulls on the lens.', '1 mark: the lens becomes thinner and flatter.', '1 mark: the effect is that light is refracted less, so the distant object is focused on the retina.'])
C('3.13.1-20','APP','Explain why an eye cannot focus on a distant object if its suspensory ligaments are damaged and cannot pull on the lens, even though the ciliary muscles relax.','The lens is not pulled thinner and flatter. It stays thick, so it refracts light too strongly and the distant object is not focused on the retina.',['1 mark: the lens in this eye is not pulled thinner and flatter.', '1 mark: the lens stays thick, so it refracts light too strongly and the distant object is not focused on the retina.'])
E('3.13.1-21','Rods and cones',['Rods are sensitive in dim light but do not distinguish colours; cones provide colour vision and work best in brighter light.','Cones are concentrated at the fovea, while rods are more abundant away from the fovea; neither is present at the blind spot.'],'Use both function and position when distinguishing these receptor types. Fine detail and colour are best when an image falls on the cone-rich fovea under adequate illumination. In dim light, rod sensitivity is useful but colour discrimination is poor. The two types are receptor cells in the retina, not muscles of the iris.',S('36.5 Vision'))
C('3.13.1-21','DIST','Distinguish rods from cones by function and distribution in the human retina.','Rods support dim-light vision without colour discrimination and are abundant away from the fovea. Cones support colour vision in brighter light and are concentrated at the fovea.',['1 mark: says that rods work in dim light without colour, whereas cones give colour vision in bright light.', '1 mark: says, in contrast, that rods are mostly away from the fovea while cones are concentrated at the fovea.'])
E('3.13.1-22','Nervous and hormonal coordination',['Nervous signals usually produce rapid, relatively short-lived responses through neurones.', 'Hormones travel in blood and often produce slower, longer-lasting responses in their target tissues.'],'The delivery route explains much of the difference. A neurone directs an impulse along a specific pathway; a hormone is carried round the whole body in the blood but acts only on organs whose cells have receptors for it. The speed and duration differences are general: adrenaline acts within seconds, while an insulin response may last for hours. Nervous responses, such as a reflex, usually start almost at once and stop when the signal stops.',None)
C('3.13.1-22','DIST','Distinguish nervous from hormonal control by usual speed and duration.','Nervous control is usually faster and shorter-lived, whereas hormonal control is often slower and longer-lasting.',['1 mark: says that nervous control is usually fast.', '1 mark: says, in contrast, that hormonal control is usually slower and the effect lasts longer.'])
C('3.13.1-22','APP','Suggest which control system best fits each observation: response X begins almost immediately after a skin stimulus and ends quickly; response Y follows a blood-borne signal and persists for hours.','X fits nervous control because it is rapid and brief. Y fits hormonal control because the signal travels in blood and its effect lasts a long time.',['1 mark: X starts at once after this stimulus and ends quickly, so it fits nervous control.', '1 mark: Y is carried in the blood and lasts for hours, so it fits hormonal control.'])

E('3.13.2-01','Drugs',['A drug is a substance taken into the body that modifies or affects chemical reactions in the body.', 'Drugs can have useful therapeutic effects as well as harmful effects.'],'The term includes medicines; it does not mean that a substance is illegal. Effects depend on the substance, the dose, the way it is taken and the person.',SY(22,'3.13.2'))
C('3.13.2-01','DEF','Define a drug.','A substance taken into the body that modifies or affects chemical reactions in the body.',['1 mark: the definition means a substance taken into the body.', '1 mark: the answer must include that it modifies or affects chemical reactions in the body.'])
E('3.13.2-02','Antibiotics',['Antibiotics treat bacterial infections by killing susceptible bacteria or inhibiting their growth.', 'Different antibiotics act on different bacterial targets, and resistant bacteria may not be controlled by a particular antibiotic.'],'An antibiotic works only against bacteria, and only against strains that are susceptible to it. Each time an antibiotic is used, susceptible bacteria are killed while any resistant bacteria survive and reproduce, so resistant strains become more common. This is natural selection, and it is why antibiotics should be used only when they are really needed.',S('22.4 Bacterial Diseases in Humans'))
C('3.13.2-02','FEATURE','Describe how antibiotics can treat bacterial infection.','They can kill susceptible bacteria. Others inhibit bacterial growth, allowing the infection to be controlled.',['1 mark: names killing of susceptible bacteria as one way antibiotics work.', '1 mark: names stopping the growth of bacteria as the other way.'])
C('3.13.2-02','WHY','Explain why the same antibiotic may fail against a resistant bacterial strain.','The resistant strain has a feature that stops this antibiotic killing it or stopping its growth. Its cells therefore survive and reproduce despite the treatment.',['1 mark: the reason is that the resistant strain has a feature that stops this antibiotic killing it or stopping its growth.', '1 mark: so its cells survive and reproduce despite the treatment.'])
E('3.13.2-03','Why antibiotics do not treat viruses',['Antibiotics act on bacterial structures or processes that viruses do not possess.', 'Viruses reproduce using host-cell machinery rather than independent bacterial metabolism.'],'For example, a medicine that disrupts bacterial cell-wall formation cannot act on a virus by that mechanism because a virus has no cell wall of the bacterial kind. The distinction is about mechanism: viruses are not simply too small for a medicine to reach. Viruses must be controlled in other ways, such as by vaccination.',S('21.2 Virus Infections and Hosts'))
C('3.13.2-03','CHAIN','Explain why an antibiotic targeting bacterial cell-wall formation does not stop a virus by the same mechanism.','Viruses have no bacterial cell wall. The antibiotic therefore has no target in the virus, so the virus is not affected.',['1 mark: when the antibiotic is given, a virus has no bacterial cell wall for it to act on.', '1 mark: so the antibiotic has no target, and the effect is that the virus is not stopped.'])
C('3.13.2-03','APP','Explain which culture is directly affected by medicine K: K blocks bacterial cell-wall formation; culture A contains susceptible bacteria and culture B contains viruses inside animal cells.','K affects culture A, because its bacteria make cell walls and K blocks this. The viruses in culture B have no bacterial cell wall, so K does not affect them.',['1 mark: K affects culture A, because its bacteria make the cell walls that K blocks.', '1 mark: the viruses in culture B have no bacterial cell wall, so this medicine does not affect them.'])
E('3.13.2-04','Depressant effects',['Excessive alcohol and heroin depress central nervous system activity.', 'Depressant action can impair coordination and, at high doses, dangerously reduce breathing.'],'A depressant is defined by reduced nervous activity, not by sadness. A person may initially seem less inhibited even while judgement and coordination are impaired. Heroin and alcohol together are especially dangerous because both can slow breathing, and their effects add together.')
C('3.13.2-04','FEATURE','Describe the meaning and one possible consequence of alcohol and heroin being depressant drugs.','They reduce central nervous system activity. Coordination can deteriorate and breathing can become dangerously depressed.',['1 mark: names reduced activity of the central nervous system as the meaning of a depressant.', '1 mark: names one valid consequence, such as poor coordination or dangerously slow breathing.'])
E('3.13.2-05','Reaction time and self-control',['Alcohol and heroin can lengthen reaction time and impair judgement and self-control.', 'Impaired coordination increases the risk of injury during activities needing quick, accurate responses.'],'Reaction time is the interval between a stimulus and the response. A longer interval means a slower reaction, not a faster one. Reduced inhibition can make a person more likely to take risks while their ability to respond is impaired. Slow reactions after drinking come from slower nervous signalling; smoke, by contrast, damages the lungs and reduces oxygen carriage, which is a different problem.')
C('3.13.2-05','FEATURE','Describe two effects of alcohol or heroin on reactions and self-control.','Reaction time can become longer. Judgement and self-control can become impaired.',['1 mark: names a longer reaction time as one effect.', '1 mark: names impaired judgement or self-control as the second effect.'])
C('3.13.2-05','WHY','Explain why a longer reaction time after depressant-drug use increases accident risk.','More time passes before the person responds to a hazard, so the hazard is more likely to cause harm before it can be avoided.',['1 mark: the reason is that more time passes before the person responds to a hazard.', '1 mark: so the hazard is more likely to cause harm before the person can avoid it.'])
C('3.13.2-05','MISCON','A student says that a person reacts slowly after drinking alcohol because the alcohol damages the lungs, so less oxygen reaches the muscles. Explain the error.','Alcohol does not slow reactions by damaging the lungs; lung damage is an effect of tobacco smoke. Alcohol acts on the nervous system: it reduces the release of neurotransmitter at synapses, so transmission is slower and reaction time is longer.',['1 mark: names the mistake: lung damage is an effect of tobacco smoke, not the way alcohol slows reactions.', '1 mark: alcohol instead acts on the nervous system, reducing neurotransmitter release at synapses, so reaction time is longer.'])
E('3.13.2-06','Alcohol and the liver',['Repeated excessive alcohol consumption can damage liver cells.', 'Long-term damage can cause scarring that reduces normal liver function.'],'The liver processes alcohol, so its cells are exposed to alcohol and to the products of its breakdown. Repeated heavy drinking kills liver cells, and scar tissue replaces them. Severe scarring disrupts the organisation needed for metabolic functions, so the liver handles nutrients, drugs and waste products less well. The longer and heavier the drinking, the greater the risk.')
C('3.13.2-06','FEATURE','Describe two linked changes in the liver caused by long-term excessive alcohol consumption.','Liver cells can be damaged and replaced by scar tissue. The scarring reduces the liver’s ability to carry out its normal functions.',['1 mark: names damage to liver cells as one change.', '1 mark: names scarring that reduces the liver’s ability to work as the linked change.'])
E('3.13.2-07','Dependence and withdrawal',['Addiction involves continued compulsive drug use despite harmful consequences.', 'Withdrawal symptoms can occur after a dependent person stops or reduces a drug.'],'Alcohol or heroin dependence can involve physical and psychological changes. Withdrawal may involve distress, sweating, shaking, nausea or other symptoms, depending on the drug and the person. Severe alcohol withdrawal can be dangerous, so dependent people need healthcare support when they stop.')
C('3.13.2-07','FEATURE','Describe addiction and withdrawal in relation to alcohol or heroin.','Addiction involves compulsive continued use despite harm. Withdrawal is the distressing physical or psychological response when a dependent person stops or reduces use.',['1 mark: names continued compulsive use despite harm as the meaning of addiction.', '1 mark: names unpleasant physical or mental symptoms when use stops as withdrawal.'])
E('3.13.2-08','Social consequences',['Problematic alcohol or heroin use can disrupt family relationships, attendance and work or school performance.', 'Impaired judgement and dependence can increase financial difficulties and risks to the user and others.'],'Each harm has a cause that can be traced: missed work can reduce income; spending on a drug can divert limited household money; impaired coordination can expose others to injury. Treatment and support can reduce these harms.')
C('3.13.2-08','FEATURE','Describe two possible social consequences of problematic alcohol or heroin use.','Relationships can be strained by disrupted responsibilities. School or work attendance and performance can deteriorate.',['1 mark: names one social consequence, such as strained family relationships.', '1 mark: names a second, such as poorer attendance or performance at school or work.'])
C('3.13.2-08','WHY','Explain how dependence on a drug can contribute to household financial difficulty.','Money spent on the drug is not available for essential needs. Missing work because of the drug can also reduce income.',['1 mark: the reason is that money spent on the drug is not available for essential needs such as food or rent.', '1 mark: missing work because of the drug can also lower income.'])
E('3.13.2-09','Injection and infection risk',['Sharing injection equipment can transfer infected blood between people.', 'Blood-borne pathogens such as HIV can enter through contaminated needles or syringes.'],'Heroin itself does not make HIV. The route is transfer of a virus that is already present in infected blood. Equipment that looks clean may still carry contaminated blood, and sharing is not made safe by the absence of visible blood. HIV is not spread by touching, sharing a room or sharing food with a person who uses drugs.',S('21.2 Virus Infections and Hosts'))
C('3.13.2-09','PROC','Describe how shared injection equipment can transmit HIV.','Blood containing HIV from an infected person stays in the needle or syringe. The next person to use it injects that blood into their bloodstream, so the virus is passed on.',['1 mark: first, blood containing HIV from an infected person stays in the needle or syringe.', '1 mark: then the next person to use the equipment injects that blood into their bloodstream, so the virus is passed on.'])
C('3.13.2-09','APP','Explain why route X presents a greater blood-borne infection risk than route Y: X reuses a syringe containing another person’s blood; Y uses new sterile equipment with no shared preparation equipment.','X can inject another person’s infected blood directly into the next user. Y uses new sterile equipment, so there is no blood from another person to carry the virus.',['1 mark: X can inject another person’s infected blood directly into the next user.', '1 mark: Y uses new sterile equipment, so this route carries no blood from another person.'])

E('3.13.3-01','Hormones',['A hormone is a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs.', 'Target organs respond because their cells have receptors suited to the hormone.'],'A hormone is made in an endocrine gland and released straight into the blood, which carries it round the whole body. Only the target organs respond, because only their cells have receptors that fit that hormone. Hormones can change metabolic activity, growth or reproduction. They are broken down, mainly in the liver, so a response fades some time after the gland stops secreting; adrenaline acts within seconds, while the effects of insulin last for hours.',SY(23,'3.13.3'))
C('3.13.3-01','DEF','Define a hormone.','A chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs.',['1 mark: the definition means a chemical substance made by a gland and carried in the blood.', '1 mark: the answer must include that it alters the activity of one or more specific target organs.'])
glands=[('02','Adrenal glands','The adrenal glands lie above the kidneys.','They secrete adrenaline.','The two adrenal glands sit one on top of each kidney. Adrenaline is carried in the blood to the heart, liver and other organs. It raises the pulse rate and the blood glucose concentration, so the body is prepared for rapid action such as running away from danger.','Identify the glands above the kidneys and their hormone.','Adrenal glands; adrenaline.'),('03','Pancreas','The pancreas lies in the abdomen near the stomach.','It secretes insulin into the blood.','The pancreas lies just below the stomach. It has two roles. It releases digestive enzymes through a duct into the small intestine, and it secretes the hormones insulin and glucagon straight into the blood. Hormones leave an endocrine gland by way of the blood, not through a duct. Insulin lowers blood glucose after a meal (3.14).','Identify the abdominal gland that secretes insulin and name its secretion.','Pancreas; insulin.'),('04','Testes','The testes are situated in the scrotum.','They secrete testosterone.','The testes hang in the scrotum, outside the main body cavity. They make sperm and they also secrete testosterone into the blood. Testosterone causes the male secondary sexual characteristics that appear at puberty, such as a deeper voice, facial hair and increased muscle growth.','Identify the glands in the scrotum and their principal sex hormone.','Testes; testosterone.'),('05','Ovaries','The ovaries lie in the pelvis, beside the uterus.','They secrete oestrogen.','The ovaries lie in the lower abdomen, one on each side of the uterus. They release eggs and secrete oestrogen into the blood. Oestrogen causes the female secondary sexual characteristics that appear at puberty, such as breast development and wider hips, and helps to control the menstrual cycle.','Identify the glands beside the uterus and name a hormone they secrete.','Ovaries; oestrogen.')]
for n,h,c1,c2,p,q,a in glands:
 E('3.13.3-'+n,h,[c1,c2],p,S('37.5 Endocrine Glands'))
 C('3.13.3-'+n,'FEATURE',q,a,['1 mark: names the gland correctly.','1 mark: names the matching hormone.'])
E('3.13.3-06','Adrenaline and metabolic activity',['Adrenaline can increase pulse rate and raise blood glucose concentration.', 'A faster circulation and greater glucose availability help support increased muscular respiration during rapid action.'],'The liver can release glucose from its glycogen store. A higher pulse rate helps deliver glucose and oxygen to active tissues. Together these changes make energy release more readily available; adrenaline is not itself a nutrient and is not burned as a fuel. Worked example: a runner sees a car and steps back quickly. The step back itself is a nervous response, over in a fraction of a second. Adrenaline is secreted into the blood at the same time, and its effects follow over the next seconds to minutes: the pulse rate rises from about 70 to about 120 beats per minute and blood glucose rises. More glucose and oxygen then reach the leg muscles, which respire faster and release energy while the runner keeps running or stays alert. The hormonal effect follows the nervous one and lasts longer. After the danger passes the adrenaline is broken down and the pulse rate returns to normal.',S('37.3 Regulation of Body Processes'))
C('3.13.3-06','CHAIN','Discuss how adrenaline helps prepare the body for increased activity.','Adrenaline causes the liver to release glucose from its glycogen store, so blood glucose rises. It increases the pulse rate, so glucose and oxygen reach the muscles faster. The muscles can then respire faster and release more energy.',['1 mark: when adrenaline increases, the liver releases glucose from its glycogen store, so blood glucose rises.', '1 mark: adrenaline also increases the pulse rate, so glucose and oxygen are delivered to the muscles faster.', '1 mark: the result is that the muscles can respire faster and release more energy for rapid action.'])
C('3.13.3-06','APP','Suggest why, when adrenaline is released in a person whose liver glycogen store has been used up, the pulse rate rises but blood glucose does not.','Adrenaline acts on the heart, so the pulse rate still rises. Adrenaline raises blood glucose by causing the liver to break down glycogen; with the store used up there is no glycogen to convert, so blood glucose does not rise.',['1 mark: adrenaline acts on the heart, so in this person the pulse rate still rises.', '1 mark: adrenaline raises blood glucose mainly by causing the liver to break down glycogen, so with no glycogen store in this situation it cannot do this.'])

E('3.14-01','Homeostasis',['Homeostasis is the maintenance of a constant internal environment.', 'In a living body, “constant” means kept within a narrow suitable range rather than exactly unchanged at every moment.'],'External conditions can vary widely while internal conditions remain suitable for cells. Examples include blood glucose concentration and core temperature. Enzyme-controlled reactions work effectively only within suitable conditions, so large deviations disrupt cell activity. Homeostatic responses regulate the internal variable; they do not make the outside environment constant.',SY(23,'3.14'))
C('3.14-01','DEF','Define homeostasis.','The maintenance of a constant internal environment, keeping conditions in the body within narrow limits.',['1 mark: the definition means keeping something constant (steady).', '1 mark: the answer must include that what is kept constant is the internal environment of the body.'])
E('3.14-02','Negative feedback',['Negative feedback detects a deviation from a suitable level and triggers responses that oppose it.', 'As the variable returns towards its normal range, the corrective response is reduced.'],'A receptor detects a change, a coordinating system processes the information, and effectors carry out a correction. “Negative” means opposing the original change, not damaging. If body temperature rises, increased cooling reduces it; when it falls back, the cooling response decreases. A response that amplified the original change would drive the variable further from its normal level and would not stabilise it.',S('33.3 Homeostasis'))
C('3.14-02','PROC','Explain how negative feedback stabilises an internal condition.','A change away from the normal level triggers a response that opposes the change. As the level returns to normal, the response is reduced, so the level stays steady.',['1 mark: first, a change away from the normal level triggers a response that opposes the change.', '1 mark: then, as the level returns to normal, the response is reduced, so the level stays steady.'])
C('3.14-02','APP','Explain why a heating controller that switches on extra heating whenever a room becomes too warm, and still more heating as the temperature rises, is not an example of negative feedback.','Its response adds to the temperature rise instead of opposing it. The temperature therefore moves further from the set level and is not brought back to normal.',['1 mark: this extra heating adds to the temperature rise instead of opposing it.', '1 mark: so the temperature moves further from the set level and is not brought back to normal.'])
E('3.14-03','Ectothermic temperature regulation',['Ectothermic animals rely largely on environmental heat rather than sustained metabolic heat production to control body temperature.','They can regulate temperature behaviourally by changing exposure to sun, shade or warm and cool surfaces.'],'An ectotherm need not have the same temperature as the surrounding air at each instant. A lizard can bask on warm rock in the morning, then move into shade when heat gain becomes excessive. Body orientation and timing of activity also change heat exchange. When conditions are too cold, biochemical activity and movement may slow, reducing the ability to seek a different place. The behaviour changes heat gain or loss rather than producing a fixed body temperature regardless of conditions.',S('33.3 Homeostasis'))
C('3.14-03','PROC','Describe how an ectothermic lizard can regulate its temperature through the day.','When it is cool it basks in the sun or on warm rock to gain heat. When it becomes too warm it moves into shade or a cool shelter, so it gains less heat.',['1 mark: first, the lizard basks in the sun or on warm rock to gain heat when it is cool.', '1 mark: then it moves into shade or a cool shelter when too warm, so it gains less heat.'])
E('3.14-04','Endothermic temperature regulation',['Endotherms generate substantial metabolic heat and regulate its retention or loss.', 'When cold they can increase heat production and reduce heat loss; when hot they can increase heat loss.'],'Birds and mammals generally maintain relatively stable core temperatures across a range of environmental temperatures. In a mammal the brain (a region called the hypothalamus) monitors the temperature of the blood. When it falls, skin arterioles narrow, muscles shiver and hairs are raised; raised fur or fluffed feathers trap a thicker layer of insulating air. Metabolic heat production requires a food supply, so regulation has an energy cost. Endotherms still exchange heat with their surroundings, and behaviour, such as seeking shade, supplements the physiological mechanisms. The human example below shows coordinated changes in muscles, skin blood flow and sweating.',S('33.3 Homeostasis'))
C('3.14-04','PROC','Describe two responses an endothermic mammal can make to cold conditions.','It makes more heat, for example by shivering. It loses less heat, for example through insulation by fur or fat and narrowing of the blood vessels in the skin.',['1 mark: one way of making more heat, such as shivering.', '1 mark: one way of losing less heat, such as narrowing of skin blood vessels or insulation by fur or fat, so the core temperature stays steady; the two points can be given in any order.'])
C('3.14-04','MECH','Describe the sequence by which an endotherm counters a fall in core temperature.','The brain detects the fall in blood temperature. Arterioles in the skin narrow (vasoconstriction), so less warm blood flows near the surface and less heat is lost. Muscles shiver, and their faster respiration releases heat. Hairs are raised, trapping a layer of insulating air.',['1 mark: the brain detects the fall in core temperature (accept the hypothalamus).', '1 mark: skin arterioles narrow (vasoconstriction), so less heat is lost from the skin.', '1 mark: shivering muscles respire faster, which releases heat.', '1 mark: hairs (or feathers) are raised, so a layer of insulating air is trapped and the effect is less heat loss.'])
E('3.14-05','Human core-temperature control',['Sweat evaporation removes heat; vasodilation increases skin blood flow and heat transfer to the surroundings when a suitable gradient exists.','Shivering increases muscle heat production; vasoconstriction reduces skin blood flow and helps conserve core heat.','Subcutaneous fat insulates by slowing heat transfer.'],'When core temperature rises, sweat glands secrete more sweat and skin arterioles widen. Heat is transferred to the skin in blood. Evaporation needs energy, taken from the skin, so it cools; sweat that drips away without evaporating provides less cooling. Humid air can limit evaporation. When cold, skin arterioles narrow, reducing warm blood near the surface, and rapid involuntary muscle contractions release additional heat through respiration. Insulation slows heat loss but does not generate heat. Vasodilation and vasoconstriction describe changes in vessel diameter, not vessels moving towards or away from the surface. These mechanisms work with negative feedback, reducing as core temperature recovers.',S('33.3 Homeostasis'))
C('3.14-05','PROC','Describe the roles of sweating and skin vasodilation when a person becomes too hot.','Sweat evaporates from the skin, which removes heat. Skin arterioles widen, so more warm blood flows near the surface and more heat is lost.',['1 mark: sweat evaporates from the skin, which removes heat.', '1 mark: skin arterioles widen (vasodilation), so more warm blood flows near the surface and more heat is lost; the two points can be given in any order.'])
C('3.14-05','MECH','Describe how vasoconstriction, insulation and shivering help a cold human maintain core temperature.','Skin arterioles narrow, so less blood flows near the surface. Less heat is therefore lost through the skin. The fat under the skin insulates because it slows heat transfer. Shivering muscles respire faster and release more heat.',['1 mark: skin arterioles narrow (vasoconstriction), so less blood flows near the skin surface.', '1 mark: less heat is therefore lost from the blood through the skin, which keeps heat in the core.', '1 mark: the layer of fat under the skin insulates because it slows heat transfer.', '1 mark: shivering muscles respire faster, so the effect is that more heat is released.'])
E('3.14-06','Blood-glucose regulation',['When blood glucose rises, pancreatic insulin promotes glucose uptake and storage, including conversion to glycogen in the liver.','When blood glucose falls, pancreatic glucagon promotes breakdown of liver glycogen and release of glucose into blood.','These opposing responses help maintain blood glucose within a suitable range by negative feedback.'],'After a meal, absorbed glucose enters the blood. Insulin is carried in blood to target tissues; it is not a digestive enzyme. The liver stores glycogen, a polymer made from glucose. Between meals, glucagon promotes release of glucose from liver stores. Distinguish the three names: glucose is the soluble sugar in blood, glycogen is the storage carbohydrate, and glucagon is the hormone. As the deviation is corrected, the hormonal response falls. Liver glycogen stores are finite, so release cannot continue at the same rate indefinitely without replenishment.',S('37.3 Regulation of Body Processes'))
C('3.14-06','PROC','Describe how insulin and the liver respond to a rise in blood glucose after a meal.','The pancreas secretes more insulin. Insulin causes cells to take up glucose and the liver to convert glucose to glycogen, so blood glucose falls.',['1 mark: first, the pancreas secretes more insulin when blood glucose is high.', '1 mark: then insulin causes cells to take up glucose and the liver to convert glucose to glycogen, so blood glucose falls.'])
C('3.14-06','MECH','Describe the complete negative-feedback response to a fall in blood glucose between meals.','The pancreas detects the low blood glucose and releases glucagon. Glucagon travels in the blood to the liver. The liver breaks down glycogen and releases glucose, so blood glucose rises. As the level recovers, glucagon release falls.',['1 mark: low blood glucose causes the pancreas to release glucagon.', '1 mark: glucagon is carried in the blood to the liver.', '1 mark: the liver breaks glycogen down to glucose and releases it, so blood glucose rises.', '1 mark: the effect is that glucagon release falls as the glucose level returns to normal.'])
C('3.14-06','MISCON','Explain the error in saying that insulin is made by the liver and sent into the intestine to emulsify fat.','Insulin is made by the pancreas and travels in the blood to lower blood glucose. Bile is made by the liver and enters the intestine, where it emulsifies fat.',['1 mark: states that insulin is made by the pancreas and carried in the blood to lower blood glucose.', '1 mark: the liver instead makes bile, which enters the intestine and emulsifies fat, so the student has confused insulin with bile.'])
E('3.14-07','Type 1 diabetes symptoms',['Type 1 diabetes involves insufficient insulin, so blood glucose can remain abnormally high.', 'Symptoms can include frequent urination, unusual thirst, tiredness and loss of body mass.'],'High glucose can be lost in urine and carries extra water with it, producing thirst. Cells cannot use the glucose effectively without insulin, which contributes to tiredness and to loss of body mass as stored nutrients are broken down. Several of these symptoms also occur in other conditions, so a blood glucose test is used to confirm diabetes.',S('37.3 Regulation of Body Processes'))
C('3.14-07','FEATURE','Outline three possible symptoms of Type 1 diabetes.','Frequent urination; unusual thirst; unexplained loss of body mass.',['1 mark for each of three correct symptoms named, for example frequent urination, unusual thirst, tiredness or loss of body mass; three different symptoms are needed for three marks.'])
E('3.14-08','Type 1 diabetes treatment',['Type 1 diabetes is managed with insulin replacement and monitoring of glucose levels.', 'Food intake and activity are coordinated with insulin under individual clinical guidance.'],'Insulin is commonly supplied by injection or pump; swallowing ordinary insulin would expose a protein to digestion. Monitoring helps avoid both high and dangerously low blood glucose. Treatment supports regulation but does not remove the condition. Replacing the missing hormone is useful because it restores the control of blood glucose that the pancreas can no longer provide. Doses are adjusted for each patient by their healthcare team.',S('37.3 Regulation of Body Processes'))
C('3.14-08','FEATURE','Outline three elements of Type 1 diabetes management.','Insulin replacement; regular glucose monitoring; coordinated food intake and activity under clinical guidance.',['1 mark for each of three correct elements named, such as insulin replacement, regular glucose monitoring, and planning food intake and activity; three different elements are needed for three marks.'])
E('3.14-09','Investigating cooling',['Cooling of warm-water tubes can model how surface conditions affect heat loss.','A wet covering can increase cooling through evaporation, while dry insulation can slow heat transfer.'],'To compare wet and dry coverings, use matching tubes, the same water volume and starting temperature, and equal fabric coverage. Keep room temperature, draughts and thermometer depth constant. Record temperature at regular intervals and compare drops over the same time; rate = temperature drop ÷ time. Repeat with fresh water and exchange positions to reduce the effect of a local draught. For surface-area comparisons, change exposed area while matching the amount of water and starting temperature as closely as possible. State what differs in the geometry; unequal water volumes can otherwise create a thermal-capacity difference. The model has no blood flow, sweating control or heat production, so its result cannot demonstrate the whole mechanism of human temperature regulation. Use warm water at a teacher-approved temperature to reduce burn risk.')
C('3.14-09','SYNTH','Describe a complete investigation comparing cooling rates of warm-water tubes covered in wet and dry fabric.','Change whether identical fabric coverings are wet or dry. Measure the temperature of the water every minute. Keep the tube size, water volume, starting temperature and air movement the same. Read the thermometer at the same depth each time. Repeat and compare the mean cooling rates.',['1 mark: changes the independent variable: whether the fabric covering is wet or dry.', '1 mark: measures the dependent variable: the temperature of the water at equal time intervals (the fall in temperature per minute).', '1 mark: keeps any two of tube size, water volume, starting temperature and air movement the same.', '1 mark: gives a workable detail of method, such as reading the thermometer at the same depth each time.', '1 mark: repeats and compares mean cooling rates.'])
C('3.14-09','LIM','Suggest a limitation of comparing a wet-covered tube in a draught with a dry-covered tube in still air, and a linked improvement.','The draught also increases cooling and evaporation, so the difference cannot be put down to the covering alone. Put both tubes in the same airflow, or both in still air.',['1 mark: explains the problem that the draught also increases cooling, so the difference cannot be put down to the covering alone.', '1 mark: suggests the improvement of putting both tubes in the same airflow, or both in still air.'])
C('3.14-09','APP','Suggest a conclusion from this tube-cooling investigation: both start at 42 °C; after 6 min the wet-covered tube is 34 °C and the dry-covered tube is 38 °C, with all other conditions matched.','The wet-covered tube cooled by 8 °C and the dry-covered tube by 4 °C, so the wet covering doubled the cooling. This supports extra cooling by evaporation.',['1 mark: in this test the wet tube fell by 8 °C and the dry tube by 4 °C over 6 min.', '1 mark: so the wet covering doubled the cooling, which supports extra cooling by evaporation.'])

